SELECT c.id
FROM customers c
WHERE c.id NOT IN (
  SELECT b.customer_id FROM blocked_customers b
);

SELECT c.id
FROM customers c
WHERE NOT EXISTS (
  SELECT 1 FROM blocked_customers b
  WHERE b.customer_id = c.id
);

CREATE TABLE inventory (
  sku TEXT PRIMARY KEY,
  quantity INTEGER NOT NULL CHECK (quantity >= 0)
);

-- PostgreSQL 15+ supports this form:
CREATE TABLE external_ids (
  source TEXT NOT NULL,
  external_id TEXT,
  UNIQUE NULLS NOT DISTINCT (source, external_id)
);
